CREATE TABLE google_checkpoints(account TEXT PRIMARY KEY,json TEXT NOT NULL,FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE google_staged_messages(account TEXT NOT NULL,generation INTEGER NOT NULL,remote_id TEXT NOT NULL,expected_revision INTEGER NOT NULL,json TEXT NOT NULL,source_hash TEXT NOT NULL,source_size INTEGER NOT NULL,PRIMARY KEY(account,generation,remote_id),FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE google_message_state(account TEXT NOT NULL,message_id TEXT NOT NULL,remote_thread_id TEXT NOT NULL,history_id TEXT NOT NULL,provider_labels_json TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account,message_id),FOREIGN KEY(account,message_id) REFERENCES messages(account,id));
CREATE TABLE google_manual_intents(account TEXT NOT NULL,message_id TEXT NOT NULL,field TEXT NOT NULL,category_id TEXT NOT NULL DEFAULT '',value INTEGER NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(account,message_id,field,category_id),FOREIGN KEY(account,message_id) REFERENCES messages(account,id));
CREATE TABLE google_page_commits(account TEXT NOT NULL,generation INTEGER NOT NULL,expected_revision INTEGER NOT NULL,fingerprint TEXT NOT NULL,next_json TEXT NOT NULL,PRIMARY KEY(account,generation,expected_revision),FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE google_category_labels(account TEXT NOT NULL,category_id TEXT NOT NULL,provider_label_id TEXT NOT NULL,PRIMARY KEY(account,category_id),UNIQUE(account,provider_label_id),FOREIGN KEY(account,category_id) REFERENCES categories(account,id));
